BEGIN;
CREATE OR REPLACE FUNCTION venue_price_reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'venue price history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS venue_price_scopes (scope_hash text PRIMARY KEY CHECK(scope_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS venue_price_source_specs (scope_hash text NOT NULL REFERENCES venue_price_scopes(scope_hash), spec_hash text NOT NULL CHECK(spec_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,spec_hash));
CREATE TABLE IF NOT EXISTS venue_price_semantics (scope_hash text NOT NULL REFERENCES venue_price_scopes(scope_hash), semantics_hash text NOT NULL CHECK(semantics_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,semantics_hash));
CREATE TABLE IF NOT EXISTS venue_price_observations (scope_hash text NOT NULL REFERENCES venue_price_scopes(scope_hash), observation_hash text NOT NULL CHECK(observation_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,observation_hash));
CREATE TABLE IF NOT EXISTS venue_price_feature07_bindings (scope_hash text NOT NULL REFERENCES venue_price_scopes(scope_hash), binding_hash text NOT NULL CHECK(binding_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,binding_hash));
CREATE TABLE IF NOT EXISTS venue_price_receipts (scope_hash text NOT NULL REFERENCES venue_price_scopes(scope_hash), receipt_hash text NOT NULL CHECK(receipt_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,receipt_hash));
CREATE TABLE IF NOT EXISTS venue_price_decisions (scope_hash text NOT NULL REFERENCES venue_price_scopes(scope_hash), decision_hash text NOT NULL CHECK(decision_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,decision_hash));
CREATE TABLE IF NOT EXISTS venue_price_request_receipts (scope_hash text NOT NULL REFERENCES venue_price_scopes(scope_hash), idempotency_key text NOT NULL, request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'), decision_hash text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,idempotency_key), FOREIGN KEY(scope_hash,decision_hash) REFERENCES venue_price_decisions(scope_hash,decision_hash));
CREATE TABLE IF NOT EXISTS venue_price_test_center_bundles (run_id text PRIMARY KEY REFERENCES agent_test_center_runs(run_id), scope_hash text NOT NULL, decision_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(scope_hash,decision_hash) REFERENCES venue_price_decisions(scope_hash,decision_hash));
DO $$ DECLARE item text; BEGIN FOREACH item IN ARRAY ARRAY['venue_price_scopes','venue_price_source_specs','venue_price_semantics','venue_price_observations','venue_price_feature07_bindings','venue_price_receipts','venue_price_decisions','venue_price_request_receipts','venue_price_test_center_bundles'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_immutable ON %I', item,item); EXECUTE format('CREATE TRIGGER %I_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION venue_price_reject_mutation()', item,item); END LOOP; END $$;
COMMIT;
